mapper.insert:
INSERT INTO campus_ingest_api_call_log (
    call_id, run_id, task_id, source_id, provider, endpoint_key, credential_ref,
    request_time, duration_ms, call_status, http_status, error_type, error_message,
    cost_units
) VALUES (
    #{callId}, #{runId}, #{taskId}, #{sourceId}, #{provider}, #{endpointKey}, #{credentialRef},
    #{requestTime}, #{durationMs}, #{callStatus}, #{httpStatus}, #{errorType}, #{errorMessage},
    #{costUnits}
)

mapper.select:
SELECT 
FROM campus_ingest_api_call_log
WHERE 1 = 1

    AND task_id = #{taskId}


    AND run_id = #{runId}


    AND provider = #{provider}


    AND call_status = #{callStatus}

ORDER BY id DESC
LIMIT 200

mapper.delete:
DELETE FROM campus_ingest_api_call_log
WHERE create_time < #{expireBefore}
ORDER BY id ASC
LIMIT #{limit}
